+import React, { useMemo } from "react";
+import PageTitle from "../components/PageTitle";
+import Navbar from "../components/Navbar";
+import Footer from "../components/Footer";
+import { useSelector } from "react-redux";
+import { useDispatch } from "react-redux";
+import { getProduct,removeErrors } from "../features/products/productSlice";
+import toast from "react-hot-toast";
+import Loader from "../components/Loader";
+import { useEffect } from "react";
+import Product from "../components/Product";
+import Pagination from "../components/Pagination";
+import {useNavigate,useSearchParams } from "react-router-dom";
+import { useState } from "react";
+
+const Products = () => {
+    const { products, productCount, loading, error , resultPerPage } =useSelector((state) => state.product);
+    const dispatch = useDispatch();
+    const navigate = useNavigate();
+
+    const [searchParams] = useSearchParams();
+   const [price, setPrice] = useState(1000);
+const [searchText, setSearchText] = useState("");
+const [sortOption, setSortOption] = useState("Newest");
+const [inStockOnly, setInStockOnly] = useState(false);
+const [minimumRating, setMinimumRating] = useState(0);
+    const keyword = searchParams.get("keyword") || "";
+    const pageFromURL = parseInt(searchParams.get("page"), 10) || 1; 
+    const category = searchParams.get("category") || "";
+    const [currentPage, setCurrentPage] = useState(pageFromURL);
+    const totalPages = Math.ceil(productCount / (resultPerPage || 8));
+
+    const handlePageChange =(pageNumber) => {
+      if (pageNumber !== currentPage) {
+        setCurrentPage(pageNumber);
+        const newSearchParams = new URLSearchParams (searchParams);
+        if (pageNumber === 1) {
+          newSearchParams.delete("page");
+        } else {
+          newSearchParams.set("page", pageNumber);
+        }
+        navigate(`?${newSearchParams.toString()}`);
+      }
+    };
+ const handleCategory = (cat) => {
+  setCurrentPage(1);
+
+  const newSearchParams = new URLSearchParams(searchParams);
+
+  newSearchParams.delete("page");
+
+  if (cat === "All") {
+    newSearchParams.delete("category");
+  } else {
+    newSearchParams.set("category", cat);
+  }
+
+  navigate(`?${newSearchParams.toString()}`);
+};
+
+const clearFilters = () => {
+  setPrice(1000);
+  setSearchText("");
+  setSortOption("Newest");
+  setInStockOnly(false);
+  setMinimumRating(0);
+
+  setCurrentPage(1);
+
+  navigate("/products");
+};
+
+   useEffect(() => {
+
+  dispatch(
+    getProduct({
+      keyword,
+      page: currentPage,
+      category,
+    })
+  );
+}, [dispatch, keyword, currentPage, category]);
+
+
+  useEffect(() =>{
+    if (error) {
+      toast.error(error.message);
+      dispatch(removeErrors());
+    }
+  },[dispatch,error]);
+   const filteredProducts = useMemo(() => {
+  let filtered = [...products];
+
+  // Search Filter
+  filtered = filtered.filter((product) =>
+    [
+      product.name || product.title,
+      product.author,
+      product.category,
+    ]
+      .join(" ")
+      .toLowerCase()
+      .includes(searchText.toLowerCase())
+  );
+
+  // Price Filter
+  filtered = filtered.filter(
+    (product) => product.price <= price
+  );
+
+  // Stock Filter
+  if (inStockOnly) {
+    filtered = filtered.filter(
+      (product) => Number(product.stock) > 0
+    );
+  }
+
+  // Rating Filter
+  filtered = filtered.filter(
+    (product) => (product.ratings || 0) >= minimumRating
+  );
+
+  // Sorting
+  switch (sortOption) {
+    case "Price Low to High":
+      filtered.sort((a, b) => a.price - b.price);
+      break;
+
+    case "Price High to Low":
+      filtered.sort((a, b) => b.price - a.price);
+      break;
+
+    case "Highest Rated":
+      filtered.sort(
+        (a, b) => (b.ratings || 0) - (a.ratings || 0)
+      );
+      break;
+
+    default:
+      break;
+  }
+
+  return filtered;
+}, [
+  products,
+  searchText,
+  price,
+  inStockOnly,
+  minimumRating,
+  sortOption,
+]);
+
+
+    return loading ?(
+        <Loader />
+  ) : (
+
+    <> 
+      <div className="flex flex-col min-h-screen bg-gray-50">
+        <PageTitle title={"Products | E-Commerce"} 
+          description="Browse our collection of books by category, author and price."
+         />
+        <Navbar /> 
+       <main className="grow container mx-auto px-3 md:px-4 py-4 md:py-8">
+           <div className="flex flex-col md:flex-row gap-4 md:gap-8">
+            <aside className="w-full md:w-64 order-2 md:order-1">
+  <div className="bg-white p-4 md:p-6 rounded-xl shadow-md md:sticky md:top-24">
+
+    <h2 className="text-2xl font-bold mb-6 border-b pb-3">
+      Filters
+    </h2>
+
+    
+    
+
+    {/* Price */}
+    <div className="mb-6">
+      <h3 className="font-semibold text-lg mb-3">
+        Price Range
+      </h3>
+
+      <input
+        type="range"
+        min="0"
+        max="2000"
+        value={price}
+        onChange={(e) => setPrice(Number(e.target.value))}
+        className="w-full"
+      />
+
+      <p className="mt-2 text-gray-600">
+        ₹0 - ₹{price}
+      </p>
+    </div>
+
+    {/* Stock */}
+    <div className="mb-6">
+      <h3 className="font-semibold text-lg mb-3">
+        Availability
+      </h3>
+
+      <label className="flex items-center gap-2">
+        <input
+          type="checkbox"
+          checked={inStockOnly}
+          onChange={(e) => setInStockOnly(e.target.checked)}
+        />
+        In Stock
+      </label>
+    </div>
+
+    {/* Rating */}
+<div>
+  <h3 className="font-semibold text-lg mb-3">
+    Customer Rating
+  </h3>
+
+  <button
+    onClick={() => setMinimumRating(4)}
+    className="block w-full text-left p-2 rounded hover:bg-gray-100"
+  >
+    ⭐⭐⭐⭐ & Above
+  </button>
+
+  <button
+    onClick={() => setMinimumRating(3)}
+    className="block w-full text-left p-2 rounded hover:bg-gray-100"
+  >
+    ⭐⭐⭐ & Above
+  </button>
+
+  <button
+    onClick={() => setMinimumRating(0)}
+    className="block w-full text-left p-2 rounded hover:bg-gray-100 text-red-500"
+  >
+    Clear Rating
+  </button>
+  
+</div>
+<button
+  onClick={clearFilters}
+  className="
+    w-full
+    mt-6
+    bg-red-500
+    hover:bg-red-600
+    text-white
+    py-2
+    rounded-xl
+    font-medium
+    transition
+  "
+>
+  Clear Filters
+</button>
+
+  </div>
+</aside>
+<section className="flex-1 bg-white p-4 rounded">
+
+  {/* Search + Sort */}
+  <div className="flex justify-between items-center bg-gray-100 p-3 rounded-lg mb-6">
+
+    <span className="text-sm text-gray-600">
+      {filteredProducts.length} results
+    </span>
+
+    <div className="flex gap-3">
+      <input
+        type="text"
+        placeholder="Search books, authors..."
+        value={searchText}
+        onChange={(e) => setSearchText(e.target.value)}
+        className="
+          border
+          border-gray-300
+          px-4
+          py-2
+          rounded-xl
+          w-64
+          focus:outline-none
+          focus:ring-2
+          focus:ring-blue-500
+        "
+      />
+
+      <select
+        value={sortOption}
+        onChange={(e) => setSortOption(e.target.value)}
+        className="
+          border
+          border-gray-300
+          px-4
+          py-2
+          rounded-xl
+          focus:outline-none
+          focus:ring-2
+          focus:ring-blue-500
+        "
+      >
+        <option>Newest</option>
+        <option>Price Low to High</option>
+        <option>Price High to Low</option>
+        <option>Highest Rated</option>
+      </select>
+    </div>
+  </div>
+
+  {/* Categories */}
+  <div
+    className="
+      bg-gradient-to-r
+      from-blue-50
+      to-indigo-50
+      rounded-2xl
+      p-4
+      mb-6
+      border
+      border-blue-100
+    "
+  >
+    <h3 className="font-semibold text-gray-700 mb-3">
+       Browse Categories
+    </h3>
+
+    <div className="flex flex-wrap gap-3">
+      {[
+        "All",
+        "Fiction",
+        "Non-Fiction",
+        "Self Help",
+        "Fantasy",
+        "Finance",
+        "Classic",
+        "Technology",
+        "Business",
+      ].map((cat) => (
+        <button
+          key={cat}
+          onClick={() => handleCategory(cat)}
+          className={`
+            px-4 py-2 rounded-full text-sm font-medium transition-all
+            ${
+              category === cat ||
+              (category === "" && cat === "All")
+                ? "bg-blue-600 text-white shadow-md"
+                : "bg-white text-gray-700 hover:bg-blue-100"
+            }
+          `}
+        >
+          {cat}
+        </button>
+      ))}
+    </div>
+  </div>
+
+  {/* Heading */}
+  <div className="mb-6">
+    <h2 className="text-2xl font-bold text-gray-800">
+      Books Collection
+    </h2>
+
+    <p className="text-gray-500 mt-1">
+      Showing {filteredProducts.length} books
+    </p>
+  </div>
+
+  {/* Products */}
+  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
+    {filteredProducts &&
+      filteredProducts.map((product) => (
+        <Product
+          key={product._id}
+          product={product}
+        />
+      ))}
+  </div>
+
+</section>
+            </div>
+            {/* Pagination Section */}
+            <div className="mt-12 flex justify-center">
+              <Pagination currentPage={currentPage} onPageChange={handlePageChange} totalPages={totalPages}/>
+            </div>
+            </main>
+            <Footer />
+        </div>
+        </>
+    );
+};
+
+export default Products;

